// Bakes the backend's theme JSON into the frontend's OFFLINE FALLBACK, and
// chartcore's icon-role vocabulary into a TypeScript table.
//
//   bun run themes            (package.json)
//
// Two generated files, one source of truth each:
//
//   backend/mivnav/features/themes/data/*.json  ->  src/core/style/themes/bundled.generated.ts
//   chartcore/assets/s52-icons/icon-roles.json  ->  src/core/style/themes/iconRoles.ts
//
// WHY BAKE THE THEMES AT ALL, when `GET /api/themes` serves them. Two reasons,
// both load-bearing:
//
//   - First paint and an offline/backend-less start must be fully themed, not
//     just day. The boat's server is the always-on device but the app is a
//     PWA that opens against a cold or unreachable backend often enough that
//     "your night chart comes up in day colours" is a real failure mode.
//   - Every unit test imports `colors.ts` synchronously and reads
//     `S52_PALETTES.night`, `THEME_BY_ID.paper2` &c. at module load. A
//     day-only fallback would make the fallback path the least-tested code in
//     the tree while breaking hundreds of tests that have nothing to do with
//     theming.
//
// The bundle is a FALLBACK, never the authority: `themes/source.ts` replaces
// it wholesale with whatever `/api/themes` serves, and `themes/index.test.ts`
// fails if this file drifts from the JSON.

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const REPO = join(import.meta.dir, "..", "..", "..");
const THEME_DATA = join(REPO, "backend", "mivnav", "features", "themes", "data");
const ROLES_JSON = join(REPO, "chartcore", "assets", "s52-icons", "icon-roles.json");
const OUT_DIR = join(import.meta.dir, "..", "..", "src", "core", "style", "themes");

/** Fields the backend JSON still carries that the frontend has no use for.
 * `spritePrefix` is the dead one: it named which of three baked raster
 * atlases a palette's symbols came from, and there are no baked atlases any
 * more (every symbol is a palette-neutral SVG the client recolours). Dropped
 * here rather than in the backend so the JSON stays a faithful record of the
 * migration until the atlas itself goes. */
const DROP = new Set(["spritePrefix"]);

export function readThemeJson(): Record<string, unknown>[] {
  const files = readdirSync(THEME_DATA).filter((f) => f.endsWith(".json"));
  const themes = files.map((f) => JSON.parse(readFileSync(join(THEME_DATA, f), "utf8")) as Record<string, unknown>);
  // The backend serves an array in `order`; a directory listing is
  // alphabetical, so sort here or the bundle and the API disagree about the
  // dropdown's order.
  themes.sort((a, b) => (a.order as number) - (b.order as number));
  for (const t of themes) for (const k of DROP) delete t[k];
  return themes;
}

function buildThemes(): string {
  const themes = readThemeJson();
  return `// GENERATED by tools/themes/build-theme-bundle.ts — do not edit.
//
// The twelve themes as the backend serves them (\`GET /api/themes\`), baked in
// as the OFFLINE / FIRST-PAINT FALLBACK. \`./source.ts\` replaces this array
// with the live one as soon as the fetch lands; \`./index.test.ts\` fails if
// this file and \`backend/mivnav/features/themes/data/*.json\` drift apart.
//
// To retune a theme, edit the JSON (or \`~/.config/mivnav/themes/\` on the
// boat, which needs no rebuild at all) and re-run \`bun run themes\`.
//
// \`AuthoredThemeDef\`, not \`ThemeDef\`: six icon roles are the theme's own S-52
// tokens and are not authored anywhere (\`./derivedIcons.ts\`), so a JSON that
// spells one out fails this file's \`satisfies\` rather than quietly shipping a
// value \`source.ts\` will override.

import type { AuthoredThemeDef } from "./types";

export const BUNDLED_THEMES: readonly AuthoredThemeDef[] = ${JSON.stringify(themes, null, 2)} as const satisfies readonly AuthoredThemeDef[];
`;
}

interface RoleEntry {
  index: string;
  day: string;
}

function buildRoles(): string {
  const json = JSON.parse(readFileSync(ROLES_JSON, "utf8")) as {
    sentinel_prefix: string;
    roles: Record<string, RoleEntry>;
    $emission: { never_emitted: string[] };
  };
  const never = new Set(json.$emission.never_emitted);
  const names = Object.keys(json.roles);
  const union = names.map((n) => `  | "${n}"`).join("\n");
  const table = Object.entries(json.roles)
    .map(([role, r]) => `  { role: "${role}", index: "${r.index}", day: "${r.day}", emitted: ${!never.has(role)} },`)
    .join("\n");
  return `// The ICON ROLE VOCABULARY, frontend side — GENERATED from
// \`chartcore/assets/s52-icons/icon-roles.json\` by
// \`tools/themes/build-theme-bundle.ts\`. Do not hand-edit; \`iconRoles.test.ts\`
// re-reads that JSON and fails on drift.
//
// chartcore renders every icon palette-neutral when asked for it
// (\`GET /api/icons/<key>.svg?roles=1\`): each painted colour is replaced by a
// reserved SENTINEL hex \`#fe00XX\`, XX being the role's index below. The client
// substitutes those for the active theme's \`icons\` block immediately before
// rasterising (\`../atonIcons.ts\`) — which is why a palette switch changes no
// \`icon-image\` id and needs no refetch.

/** One role's sentinel index, as written in \`icon-roles.json\`. */
export interface IconRoleDef {
  role: IconRole;
  /** Two lowercase hex digits — the tail of the \`#fe00XX\` sentinel. */
  index: string;
  /** What the ARTWORK is painted in — the hex chartcore replaced with this
   * role's sentinel. The acceptance test for the whole colour pipeline: feed
   * these values back and a roles-mode icon is byte-identical to the baked
   * one (chartcore's \`roles_mode_round_trips_to_byte_identical_day_output\`).
   *
   * NOT necessarily what the \`day\` THEME renders the role as any more: the
   * six roles in \`./derivedIcons.ts\`'s \`DERIVED_ICON_ROLES\` are each an S-52
   * token, and day's tuned LITRD/LITGN/LITYW/CHMGD are a visible deltaE 13–18
   * from the presentation-library hexes baked into the artwork. Day's other
   * 29 roles are still exactly these values. */
  day: string;
  /** Whether chartcore ever actually emits this sentinel. 11 of the 35 never
   * do — see \`icon-roles.json\`'s \`$emission\` block (four \`art-grey-*\` roles
   * that turned out to be Inkscape editor metadata, and seven \`lit-*\` roles
   * an upstream-parity bug in \`recolor_variant\` makes unreachable). Kept so
   * the indices stay stable against the table baked into \`roles.rs\`, but a UI
   * must not offer a control for them: editing one renders nothing. */
  emitted: boolean;
}

/** Every role name, exactly as \`icon-roles.json\` spells it. */
export type IconRole =
${union};

/** A theme's \`icons\` block: one hex per role. */
export type IconRoleColors = Record<IconRole, string>;

/** The sentinel block chartcore reserves — no real artwork hex collides. */
export const ICON_SENTINEL_PREFIX = "${json.sentinel_prefix}";

export const ICON_ROLES: readonly IconRoleDef[] = [
${table}
];

/** The roles a UI may offer a control for — the ones chartcore actually
 * emits. A control for any other role would silently render nothing. */
export const EMITTED_ICON_ROLES: readonly IconRoleDef[] = ICON_ROLES.filter((r) => r.emitted);

/** \`#fe00XX\` for one role. */
export function iconRoleSentinel(index: string): string {
  return ICON_SENTINEL_PREFIX + index;
}

/**
 * Replace every role sentinel in a roles-mode SVG with the theme's own hex.
 *
 * Driven by the ROLE TABLE, not by scanning the document for \`#fe00..\`: a
 * sentinel with no entry in \`colors\` (a hand-authored theme missing a key, or
 * one of the never-emitted roles) then simply keeps its sentinel rather than
 * resolving to some arbitrary fallback, and a role whose sentinel is absent
 * costs one failed replace. Case-insensitive because the notation chartcore
 * emits (lowercase \`#rrggbb\`, verified in \`icon-roles.json\`'s
 * \`$measurement\`) is a fact about today's usvg writer, not a guarantee.
 *
 * NOT keyed on the ARTWORK hex: several roles share one
 * (\`lit-white\`/\`lit-yellow\` are both \`#fab20b\` in the baked SVGs,
 * \`obj-magenta\`/\`warn-magenta\` both \`#ec008c\`), so matching on it would
 * silently collapse roles the sentinel scheme exists to keep separable — even
 * though the pairs that share an artwork hex are also the ones
 * \`./derivedIcons.ts\` resolves to a single S-52 token today.
 */
export function substituteIconRoles(svg: string, colors: Partial<IconRoleColors>): string {
  let out = svg;
  for (const { role, index } of ICON_ROLES) {
    const hex = colors[role];
    if (!hex) continue;
    out = out.replace(new RegExp(iconRoleSentinel(index), "gi"), hex);
  }
  return out;
}
`;
}

if (import.meta.main) {
  writeFileSync(join(OUT_DIR, "bundled.generated.ts"), buildThemes());
  writeFileSync(join(OUT_DIR, "iconRoles.ts"), buildRoles());
  console.log("wrote bundled.generated.ts + iconRoles.ts");
}
